        uint256 initialBalanceTarget = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        // Record initial balance of attacker
        uint256 initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);

